@startuml

abstract class Well {
  + code : string
}

class OnshoreWell --|> Well {
  + surfaceExtension : float
}

class OffshoreWell --|> Well {
  + installationYear : int
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class Extraction {
  + quantityMillionsBarrels : float
}

Well "1" *-- "0..*" Extraction
Extraction "*" -- "1" OilCompany
OffshoreWell "0..*" o-- "0..1" GeographicalArea

@enduml

